function check(actual, expected, what) {
    if (!Object.is(actual, expected))
        throw new Error(what + ": " + String(actual) + " instead of " + String(expected));
}

function selectsVeryLong(s) { switch (s) { case "": return 1; case "": return 2; case "b": return 3; case "cc": return 4; default: return 0; } }
function selectsLong(s) { switch (s) { case "": return 1; case "b": return 3; case "cc": return 4; default: return 0; } }
function selectsShort(s) { switch (s) { case "yyy": return 1; case "b": return 3; case "cc": return 4; default: return 0; } }
for (const f of [selectsVeryLong, selectsLong, selectsShort])
    noInline(f);

function resolved(character, length) { return character.repeat(length); }
function rope(character, length) { return character.repeat(length - 1) + character; }
function slice(character, length) { const base = "-" + character.repeat(length); Symbol(base); return base.slice(1); }
function sliceOfWide(character, length) { const base = "Ā" + character.repeat(length); Symbol(base); return base.slice(1); }
function wide(character, length) { const string = sliceOfWide(character, length); Symbol(string); return string; }
function differsAtTheEnd(character, length) { const string = character.repeat(length - 1) + "-"; Symbol(string); return string; }
function differsAtTheStart(character, length) { const string = "-" + character.repeat(length - 1); Symbol(string); return string; }
for (const [make, isRopeExpected, is8BitExpected] of [[resolved, false, true], [rope, true, true], [slice, true, true], [sliceOfWide, true, false], [wide, false, false], [differsAtTheEnd, false, true], [differsAtTheStart, false, true]]) {
    check(isRope(make("y", 65536)), isRopeExpected, make.name + " makes a rope");
    check(is8BitString(make("y", 65536)), is8BitExpected, make.name + " makes a string of 8-bit characters");
}

for (const make of [resolved, rope, slice, sliceOfWide, wide]) {
    for (const [length, expected] of [[65533, 0], [65534, 0], [65535, 1], [65536, 2], [65537, 0], [70000, 0], [131071, 0], [131072, 0], [3, 0]]) {
        for (let again = 0; again < 2; again++)
            check(selectsVeryLong(make("y", length)), expected, make.name + " of " + length + " for very long labels");
    }
    for (const [length, expected] of [[65532, 0], [65533, 0], [65534, 1], [65535, 0], [65536, 0], [70000, 0], [131070, 0]])
        check(selectsLong(make("z", length)), expected, make.name + " of " + length + " for a long label");
    for (const [length, expected] of [[2, 0], [3, 1], [4, 0], [65535, 0], [65536, 0], [65539, 0]])
        check(selectsShort(make("y", length)), expected, make.name + " of " + length + " for short labels");
}
for (const make of [differsAtTheEnd, differsAtTheStart]) {
    for (const length of [65534, 65535, 65536, 65537])
        check(selectsVeryLong(make("y", length)), 0, make.name + " of " + length + " for very long labels");
    for (const length of [65533, 65534, 65535])
        check(selectsLong(make("z", length)), 0, make.name + " of " + length + " for a long label");
}
{
    const once = resolved("y", 65536);
    check(selectsVeryLong(once), 2, "a string of 65536");
    check(selectsVeryLong(once + "y"), 0, "the same and one more");
    check(selectsVeryLong(once.slice(1)), 1, "the same and one less");
    check(selectsVeryLong(once.slice(2)), 0, "the same and two less");
}
for (const f of [selectsVeryLong, selectsLong, selectsShort]) {
    check(f("b"), 3, f.name + " of a short string");
    check(f("cc"), 4, f.name + " of another short string");
    check(f("c" + "c".repeat(1)), 4, f.name + " of a short rope");
    check(f("d"), 0, f.name + " of a string that is no label");
    check(f(""), 0, f.name + " of the empty string");
    check(f(5), 0, f.name + " of a number");
    check(f(undefined), 0, f.name + " of undefined");
    check(f(new String("b")), 0, f.name + " of a wrapped string");
}

console.log("passed");
